@pydantic.model_validator(mode="before")
@classmethod
def validate_input(cls, data: Any):
    """Normalize varied LM output formats into the canonical ``tool_calls`` structure.

    Returns a plain Python structure (dict/list/string), not a ``ToolCalls`` instance, so that
    downstream pydantic validation can construct the final model.
    """
    if isinstance(data, cls):
        return data.model_dump()

    if isinstance(data, str):
        try:
            data = json.loads(data)
        except (json.JSONDecodeError, ValueError):
            return data

    if isinstance(data, dict):
        if "tool_calls" in data:
            return data
        if "name" in data and "args" in data:
            return {"tool_calls": [data]}
        return data

    if isinstance(data, list):
        return {"tool_calls": data}

    return data
